{\"ref\":\"num:node_gpus\",\"name\":\"GPUs per instance\",\"value\":8,\"unit\":\"GPUs\",\"basis\":\"CITED\",\"quote\":\"8x — NVIDIA A100 SXM | VRAM/GPU 40 GB | vCPUs 124 | RAM 1800 GiB | STORAGE 5.8 TiB SSD | PRICE/GPU/HR* $1.99\",\"page_setting\":\"Lambda on-demand pricing, 8x NVIDIA A100 SXM 40 GB node.\",\"url\":\"https://lambda.ai/pricing\"}

